entries[5141] = { ["name"] = "Buch des Nachwachsens", ["text"] = "Klassen: Druide\nBenötigt Stufe 12\nBenutzen: Lehrt 'Verjüngung' (Rang 1).\nHeilt ein befreundetes Ziel um 0 sowie zusätzlich im Verlauf von 6 Sek. um insgesamt [Quellwert]. [ Glyphe 'Nachwachsen' : Die Effektdauer von 'Nachwachsen' wird jedes Mal, wenn der Zauber ein Ziel mit 50% Gesundheit oder weniger heilt, automatisch auf 6 Sek. zurückgesetzt ] [ Baum des Lebens : Baum des Lebens: Spontanzauber. ]\nVerkaufspreis:", ["unresolvedValues"] = true }
