entries[5158] = { ["name"] = "Buch der Gelassenheit", ["text"] = "Klassen: Druide\nBenötigt Stufe 30\nBenutzen: Lehrt 'Gelassenheit' (Rang 1).\nHeilt die 5 Gruppen- oder Schlachtzugsmitglieder im Umkreis von 40 Metern, deren Gesundheit am niedrigsten ist, 8 Sek. lang alle 2 Sek. um 0 Gesundheit.\n\nZusätzlich heilt 'Gelassenheit' 8 Sek. lang alle 2 Sek. um 0 Gesundheit. Bis zu 3-mal stapelbar. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten.\nVerkaufspreis:" }
