entries[5696] = { ["name"] = "Schrifttafel des Schocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Schock' (Rang 1).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 25 to 28 Schaden zu.\nVerkaufspreis:" }
entries[5697] = { ["name"] = "Schrifttafel des Totems der Heilung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Heilung' (Rang 1).\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem regeneriert 5 Min. lang alle 2 Sek. [( 1 + (Spell power * 0.0827) * (( 1 * 1 )))] Gesundheit aller Gruppenmitglieder in einem Umkreis von 30 Metern [ Glyphe 'Totem des heilenden Flusses' : und erhöht den Feuer-, Frost- und Naturwiderstand aller Gruppen- und Schlachtzugsmitglieder innerhalb von 30 Metern um [( 85 <= 70 ? 85 : ( 85 <= 80 ? 85 + ( 85 - 70) * 5 : 85 + ( 85 - 70) * 5 + ( 85 - 80) * 7))] ].\nVerkaufspreis:" }
entries[5698] = { ["name"] = "Schrifttafel des Blitzschlagschildes", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde wird von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifer 12 Naturschaden. Dies kostet einen Kugelblitz [ Glyphe 'Blitzschlagschild' : wird die Anzahl der Aufladungen jedoch nicht unter 3 senken ]. Es kann immer nur ein einzelner Kugelblitz alle paar Sekunden ausgelöst werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)\nVerkaufspreis:" }
entries[5699] = { ["name"] = "Schrifttafel des Geisterwolfs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Geisterwolf' (Rang 1).\nVerwandelt den Schamanen in einen Geisterwolf, wodurch sein Bewegungstempo um 30% erhöht wird. Als Geisterwolf wird der Schamane durch Effekte, die sein Bewegungstempo einschränken, weniger gehindert.\nVerkaufspreis:" }
