entries[5703] = { ["name"] = "Schrifttafel des Donnerknalls", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Donnerknall' (Rang 1).\nÜberzieht Feinde im Umkreis von 8 Metern mit 23 Schaden und erhöht die Zeit zwischen ihren Angriffen 30 Sek. lang um 20 %. Schaden wird durch Angriffskraft erhöht.\nVerkaufspreis:" }
